#!/usr/bin/env node
/**
 * Consistency guard for the published plugin repo.
 *
 * Everything here is generated by `scripts/publish-plugin.mjs` in the source
 * repo, so these checks are aimed at the ways that generation can go wrong
 * quietly — a manifest left on the previous version, the two skill copies
 * drifting apart, a manifest naming a skills directory other than the one
 * Claude Code auto-discovers (which registers the skill twice and charges the
 * context budget twice), a staging URL reaching a public manifest, or a
 * declared MCP server that is not actually serving (checked on releases only).
 *
 * Run it locally the same way CI does:
 *
 *     node .github/scripts/verify-manifests.mjs            # consistency only
 *     node .github/scripts/verify-manifests.mjs v0.37.1    # also match the tag
 */

import { readFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../..", import.meta.url));
const failures = [];
const fail = (msg) => failures.push(msg);

const read = (rel) => {
  try {
    return JSON.parse(readFileSync(join(root, rel), "utf8"));
  } catch (err) {
    fail(`${rel}: cannot read or parse — ${err.message}`);
    return undefined;
  }
};

const claude = read(".claude-plugin/plugin.json");
const market = read(".claude-plugin/marketplace.json");
const codex = read(".codex-plugin/plugin.json");
const gemini = read("gemini-extension.json");

// --- 1. Every manifest carries the same version -----------------------------
//
// The plugin cache is keyed by version. A manifest claiming a version the
// release does not have ships a stale cache to everyone who installs it.

const versions = {
  ".claude-plugin/plugin.json": claude?.version,
  ".claude-plugin/marketplace.json (metadata)": market?.metadata?.version,
  ".claude-plugin/marketplace.json (plugins[0])": market?.plugins?.[0]?.version,
  ".codex-plugin/plugin.json": codex?.version,
  "gemini-extension.json": gemini?.version,
};

const distinct = [...new Set(Object.values(versions).filter(Boolean))];
if (distinct.length > 1) {
  fail(
    `manifest versions disagree:\n${Object.entries(versions)
      .map(([k, v]) => `      ${v ?? "(missing)"}  ${k}`)
      .join("\n")}`,
  );
}
for (const [file, v] of Object.entries(versions)) {
  if (!v) fail(`${file}: no version`);
}

// --- 2. On a release, the version is the tag --------------------------------

const tag = process.argv[2];
if (tag) {
  const expected = tag.replace(/^v/, "");
  for (const [file, v] of Object.entries(versions)) {
    if (v && v !== expected) fail(`${file}: version ${v} but the tag is ${tag}`);
  }
}

// --- 3. The two skill copies are identical ----------------------------------
//
// `skills/` is what Claude Code, Codex and Gemini read; `.agents/skills/` is
// the copy other agents read. One source publishes both, so any difference
// means something was hand-edited here.

const A = "skills/bookipi-cli";
const B = ".agents/skills/bookipi-cli";

const walk = (dir, base = dir) => {
  const out = [];
  for (const entry of readdirSync(join(root, dir))) {
    const rel = join(dir, entry);
    if (statSync(join(root, rel)).isDirectory()) out.push(...walk(rel, base));
    else out.push(relative(base, rel));
  }
  return out.sort();
};

if (!existsSync(join(root, A))) fail(`${A}: missing`);
else if (!existsSync(join(root, B))) fail(`${B}: missing`);
else {
  const a = walk(A);
  const b = walk(B);
  for (const f of a.filter((f) => !b.includes(f))) fail(`${B}/${f}: missing (present in ${A})`);
  for (const f of b.filter((f) => !a.includes(f))) fail(`${A}/${f}: missing (present in ${B})`);
  for (const f of a.filter((f) => b.includes(f))) {
    const left = readFileSync(join(root, A, f));
    const right = readFileSync(join(root, B, f));
    if (!left.equals(right)) fail(`${f}: differs between ${A} and ${B}`);
  }
  if (!existsSync(join(root, A, "SKILL.md"))) fail(`${A}/SKILL.md: missing`);
}

// --- 4. Both Claude paths name the auto-discovered directory ----------------
//
// Claude Code auto-discovers ./skills/ ON TOP OF whatever the manifest
// declares. Naming a different directory registers the same skill twice.

for (const entry of claude?.skills ?? []) {
  if (!entry.startsWith("./skills/")) {
    fail(
      `.claude-plugin/plugin.json: skills entry "${entry}" is outside ./skills/ — ` +
        `auto-discovery would register the skill a second time`,
    );
  }
  if (!existsSync(join(root, entry))) {
    fail(`.claude-plugin/plugin.json: skills entry "${entry}" does not exist`);
  }
}
if (codex && codex.skills !== "./skills/") {
  fail(`.codex-plugin/plugin.json: skills is "${codex.skills}", expected "./skills/"`);
}

// --- 5. Branding assets the Codex manifest points at exist ------------------

for (const key of ["composerIcon", "logo"]) {
  const p = codex?.interface?.[key];
  if (p && !existsSync(join(root, p))) {
    fail(`.codex-plugin/plugin.json: interface.${key} "${p}" does not exist`);
  }
}

// --- 6. No staging hosts in a public manifest -------------------------------

const MANIFESTS = [
  ".claude-plugin/plugin.json",
  ".claude-plugin/marketplace.json",
  ".codex-plugin/plugin.json",
  "gemini-extension.json",
];
for (const f of MANIFESTS) {
  const body = readFileSync(join(root, f), "utf8");
  const leaked = body.match(/https?:\/\/[^"\s]*\b(dev|staging|bkpi\.co)\b[^"\s]*/);
  if (leaked) fail(`${f}: non-production URL ${leaked[0]}`);
}

// --- 7. A declared MCP server is https, and on a release, actually serving ---
//
// The plugin starts its MCP servers automatically when it is enabled, so a URL
// that does not resolve is a failed connection in front of every user who
// installs. Reachability is only checked on a release, where it is worth
// failing the run over; on push and PR the shape is checked and nothing is
// dialled.

// Claude and Codex name the transport in `type` and the endpoint in `url`;
// Gemini picks the transport by key — `httpUrl` for streamable HTTP, `url` for
// SSE — and has no `type` at all. All three are normalised to a URL here.

const remotes = [];
for (const [file, manifest] of [
  [".claude-plugin/plugin.json", claude],
  [".codex-plugin/plugin.json", codex],
]) {
  // Codex also allows `"mcpServers": "./.mcp.json"`; only the inline object
  // form is checkable from here.
  if (typeof manifest?.mcpServers !== "object") continue;
  for (const [name, cfg] of Object.entries(manifest.mcpServers)) {
    if (cfg.type === "http" || cfg.type === "sse") {
      remotes.push({ file, name, url: cfg.url });
    }
  }
}
for (const [name, cfg] of Object.entries(gemini?.mcpServers ?? {})) {
  const url = cfg.httpUrl ?? cfg.url;
  if (url) remotes.push({ file: "gemini-extension.json", name, url });
}

for (const { file, name, url } of remotes) {
  if (!url?.startsWith("https://")) {
    fail(`${file}: mcpServers.${name} must be https — got "${url}"`);
  }
}

// The two manifests describe the same connector, so they must name the same
// endpoint. Divergence means one was edited and the other forgotten.
const endpoints = [...new Set(remotes.map((r) => r.url).filter(Boolean))];
if (endpoints.length > 1) {
  fail(`manifests declare different MCP endpoints: ${endpoints.join(", ")}`);
}

if (tag) {
  for (const url of endpoints) {
    const health = new URL("/health", url).toString();
    try {
      const res = await fetch(health, { signal: AbortSignal.timeout(15000) });
      if (!res.ok) fail(`${health} returned ${res.status}`);
    } catch (err) {
      fail(`${health} is unreachable — ${err.message}`);
    }
  }
}

// --- Report -----------------------------------------------------------------

if (failures.length > 0) {
  console.error(`\n✗ ${failures.length} problem(s):\n`);
  for (const f of failures) console.error(`  • ${f}`);
  console.error("");
  process.exit(1);
}

console.log(`✔ manifests agree on ${distinct[0]}, skill copies identical`);
